I'll create a React error boundary component with fallback UI, retry functionality, and error logging.

**`ErrorBoundary.tsx`**

```tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("[ErrorBoundary]", error.message);
    console.error("Component stack:", info.componentStack);
    this.props.onError?.(error, info);
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (error) {
      if (fallback) return fallback(error, this.reset);
      return <DefaultFallback error={error} onRetry={this.reset} />;
    }

    return children;
  }
}

function DefaultFallback({ error, onRetry }: { error: Error; onRetry: () => void }) {
  return (
    <div role="alert" style={styles.container}>
      <h2 style={styles.title}>Something went wrong</h2>
      <pre style={styles.message}>{error.message}</pre>
      <button onClick={onRetry} style={styles.button}>
        Try again
      </button>
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    padding: "2rem",
    border: "1px solid #f87171",
    borderRadius: "8px",
    backgroundColor: "#fef2f2",
    color: "#991b1b",
    maxWidth: "480px",
    margin: "2rem auto",
    fontFamily: "sans-serif",
  },
  title: { margin: "0 0 0.75rem", fontSize: "1.125rem" },
  message: {
    margin: "0 0 1rem",
    padding: "0.75rem",
    background: "#fee2e2",
    borderRadius: "4px",
    fontSize: "0.875rem",
    whiteSpace: "pre-wrap",
    wordBreak: "break-word",
  },
  button: {
    padding: "0.5rem 1.25rem",
    background: "#dc2626",
    color: "#fff",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
    fontSize: "0.875rem",
  },
};
```

**Usage**

```tsx
// Basic — uses default fallback UI
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// Custom fallback
<ErrorBoundary
  fallback={(error, retry) => (
    <div>
      <p>Oops: {error.message}</p>
      <button onClick={retry}>Retry</button>
    </div>
  )}
  onError={(error, info) => reportToSentry(error, info)}
>
  <MyComponent />
</ErrorBoundary>
```

**Key design decisions:**

- `getDerivedStateFromError` — captures the error into state, triggering the fallback render (this is the React-required static lifecycle for error boundaries).
- `componentDidCatch` — side-effect hook for logging; fires after render, so it won't interfere with the fallback paint.
- `reset` resets state to `null`, which re-renders `children` — the "retry" mechanism.
- `fallback` prop accepts a render function `(error, reset) => ReactNode` so callers get full control without losing the retry callback.
- `onError` prop is a clean escape hatch for external loggers (Sentry, Datadog, etc.) without coupling the component to any specific SDK.
